const D = { hue: 28, energy: .55, speed: 1, density: .6, scale: 1, x: .5, y: .45, n: 120, cohesion: 1, align: 1, separate: 1, wind: .5, style: 'dusk', act: 'migrate', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU2 = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(8, Math.min(300, Math.round(P.n)));
const ho = P.hue - 28;

const STY = {
  dusk:      { sky:[[268,42,22],[8,58,42],[32,84,66]], bird:[24,22,7],  add:false },
  ink:       { sky:[[34,7,90],[30,11,76],[28,15,64]],  bird:[30,14,28], add:false },
  thermal:   { sky:[[232,64,9],[248,54,13],[262,48,19]], bird:[20,92,96], add:true },
  trails:    { sky:[[250,52,7],[258,46,11],[246,40,15]], bird:[40,82,100], add:true },
  blueprint: { sky:[[214,74,11],[212,66,17],[210,58,23]], bird:[190,82,96], add:false } };
const st = STY[P.style] || STY.dusk;

// ---- cached dusk-sky gradient buffer ----
const skyKey = width + 'x' + height + P.style + P.seed + Math.round(P.hue);
if (!S.sky || S.skyKey !== skyKey) {
  if (!S.sky) S.sky = createGraphics(width, height);
  else S.sky.resizeCanvas(width, height);
  const g = S.sky;
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke();
  const c = st.sky;
  for (let yy = 0; yy < height; yy++) {
    const t = yy / height;
    let a, b2, f;
    if (t < 0.5) { a = c[0]; b2 = c[1]; f = t / 0.5; }
    else { a = c[1]; b2 = c[2]; f = (t - 0.5) / 0.5; }
    const hh = hw(a[0] + (b2[0] - a[0]) * f + ho);
    const ss = a[1] + (b2[1] - a[1]) * f;
    const bb = a[2] + (b2[2] - a[2]) * f;
    g.fill(hh, ss, bb);
    g.rect(0, yy, width, 1);
  }
  // deterministic star / speckle field for upper sky
  const nst = Math.floor(40 + P.seed % 30);
  for (let i = 0; i < nst; i++) {
    const sxp = fr(i * 5 + 1) * width;
    const syp = fr(i * 5 + 2) * height * 0.5;
    const sa = st.add ? 30 : 18;
    g.fill(hw(st.bird[0] + ho + 20), 10, st.add ? 90 : 82, sa * fr(i * 5 + 3));
    g.rect(sxp, syp, 1.4, 1.4);
  }
  S.skyKey = skyKey;
}

image(S.sky, 0, 0);

// slow-drifting dusk glow (sky evolution + luminance lift)
push();
blendMode(ADD);
noStroke();
const gAlpha = (0.6 + 0.8 * P.density);
const gx = width * (0.5 + 0.34 * Math.sin(K.t * 0.05));
const gy = height * (0.6 - 0.06 * Math.sin(K.t * 0.031));
for (let r = 0; r < 3; r++) {
  fill(hw(30 + ho + 10 * Math.sin(K.t * 0.02)), 46, 30, 7 * gAlpha);
  ellipse(gx, gy, u * (1.35 - r * 0.28), u * (0.55 - r * 0.11));
}
blendMode(BLEND);
pop();

// ---- flock init / rebuild ----
if (!S.b || S.bn !== N || S.bseed !== P.seed) {
  S.b = [];
  for (let i = 0; i < N; i++) {
    S.b.push({
      x: fr(i * 2 + 1) * width,
      y: fr(i * 2 + 2) * height * 0.85,
      vx: (fr(i * 3 + 5) - 0.5) * 2,
      vy: (fr(i * 3 + 7) - 0.5) * 2,
      ph: fr(i + 9) * TAU2 });
  }
  S.bn = N; S.bseed = P.seed;
}

const inten = 0.5 + 0.6 * K.intensity;
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = {
  migrate: [[1,1,1,0],[1.2,1.1,.9,.2],[.7,1.3,.8,.6],[1,1,1,.3],[.5,.8,1.4,.9],[1.3,1,.8,.1],[1,1.2,1,.5],[.8,.9,1.1,.4]],
  gather:  [[1.4,.9,.8,0],[1.6,1,.7,.1],[1.3,1.1,.9,.2],[1.5,.9,.8,.1],[1.2,1,1,.3],[1.5,1,.7,0],[1.3,1.1,.9,.2],[1.4,.9,.8,.1]],
  scatter: [[.5,1.2,1.5,.3],[.4,1,1.7,.6],[.6,1.3,1.4,.4],[.3,.9,1.8,.8],[.5,1.1,1.5,.5],[.4,1,1.6,.7],[.6,1.2,1.3,.3],[.5,1,1.5,.5]] };
const w = (ACT[P.act] || ACT.migrate)[sec];
const cohW = P.cohesion * w[0], aliW = P.align * w[1], sepW = P.separate * w[2], swirlW = w[3];

const cxT = width * (P.x + 0.24 * Math.sin(K.t * 0.06 + 1));
const cyT = height * (P.y + 0.16 * Math.sin(K.t * 0.043));
const spd = (1.3 + 2.0 * P.energy) * inten * P.speed;
const wa = K.t * 0.07;
const windx = Math.cos(wa) * P.wind * 0.26 * P.speed;
const windy = Math.sin(wa * 0.7) * P.wind * 0.12 * P.speed;
const scat = A.bass * 1.6 + K.pulse * 0.25;
const bi = Math.floor(K.beat);

const r2 = (u * 0.13) * (u * 0.13);
const sep2 = (u * 0.045) * (u * 0.045);
const hb = width * 0.5, vb = height * 0.5;
const b = S.b;

// ---- simulate ----
for (let i = 0; i < N; i++) {
  const p = b[i];
  let ax = 0, ay = 0, cx = 0, cy = 0, sx = 0, sy = 0, cnt = 0;
  for (let j = 0; j < N; j++) {
    if (j === i) continue;
    const o = b[j];
    let dx = o.x - p.x, dy = o.y - p.y;
    if (dx > hb) dx -= width; else if (dx < -hb) dx += width;
    if (dy > vb) dy -= height; else if (dy < -vb) dy += height;
    const d2 = dx * dx + dy * dy;
    if (d2 < r2) {
      ax += o.vx; ay += o.vy;
      cx += dx; cy += dy; cnt++;
      if (d2 < sep2 && d2 > 0.01) { sx -= dx / d2 * 40; sy -= dy / d2 * 40; }
    }
  }
  if (cnt > 0) {
    ax /= cnt; ay /= cnt; cx /= cnt; cy /= cnt;
    p.vx += ax * 0.04 * aliW + cx * 0.0011 * cohW + sx * 0.02 * sepW;
    p.vy += ay * 0.04 * aliW + cy * 0.0011 * cohW + sy * 0.02 * sepW;
  }
  let tx = cxT - p.x, ty = cyT - p.y;
  const tl = Math.hypot(tx, ty) + 0.001; tx /= tl; ty /= tl;
  p.vx += tx * 0.016 + (-ty) * swirlW * 0.07;
  p.vy += ty * 0.016 + (tx) * swirlW * 0.07;
  p.vx += windx + (fr(i + bi) - 0.5) * scat;
  p.vy += windy + (fr(i * 7 + bi) - 0.5) * scat;
  let sp = Math.hypot(p.vx, p.vy);
  if (sp > spd) { p.vx = p.vx / sp * spd; p.vy = p.vy / sp * spd; sp = spd; }
  const floor = spd * 0.38;
  if (sp < floor) { const bb = floor / (sp + 0.001); p.vx *= bb; p.vy *= bb; sp = floor; }
  p.x += p.vx; p.y += p.vy;
  if (p.x < 0) p.x += width; else if (p.x >= width) p.x -= width;
  if (p.y < 0) p.y += height; else if (p.y >= height) p.y -= height;
}

// ---- render ----
noStroke();
if (st.add) blendMode(ADD);
const size = u * 0.013 * P.scale;
const bh = hw(st.bird[0] + ho);
for (let i = 0; i < N; i++) {
  const p = b[i];
  const ang = Math.atan2(p.vy, p.vx);
  const flap = 0.5 + 0.5 * Math.sin(K.beat * TAU2 * 1.6 + p.ph);
  push();
  translate(p.x, p.y);
  rotate(ang);
  if (P.style === 'trails') {
    const tl2 = Math.min(Math.hypot(p.vx, p.vy) * 4, size * 7);
    stroke(bh, st.bird[1], st.bird[2], 60);
    strokeWeight(size * 0.5);
    line(0, 0, -tl2, 0);
    noStroke();
    fill(bh, st.bird[1], st.bird[2], 92);
    ellipse(0, 0, size * 0.9, size * 0.9);
  } else if (P.style === 'blueprint') {
    stroke(bh, st.bird[1], st.bird[2], 88);
    strokeWeight(1);
    line(0, 0, -size * 2.2, 0);
    const wg = size * (0.6 + flap * 1.0);
    line(0, 0, -size * 1.4, wg);
    line(0, 0, -size * 1.4, -wg);
    noStroke();
  } else {
    fill(bh, st.bird[1], st.bird[2], st.add ? 66 : 92);
    const wy = size * (0.35 + flap * 1.15);
    beginShape();
    vertex(size * 1.3, 0);
    vertex(-size * 0.9, wy);
    vertex(-size * 0.4, 0);
    vertex(-size * 0.9, -wy);
    endShape(CLOSE);
  }
  pop();
}
if (st.add) blendMode(BLEND);
